// ErrInsecureBaseURL is what every call answers when the client's base URL is
// not https and not a loopback address, before anything is sent: the API key
// would cross the network in clear text.
var ErrInsecureBaseURL = errors.New("perata: the base URL must be https (http is accepted only for localhost, 127.0.0.0/8 and ::1), so the API key is never sent in clear text")

// Client talks to Peráta's API with one organization's API key. The key says
// the organization and the environment: prk_test_… is the test environment,
// prk_live_… the live one. The usage ingestion takes another credential, a
// usage source's (pus_test_…, pus_live_…), which a client built with it sends
// the same way.
type Client struct {
	apiKey  string
	baseURL string
	http    *http.Client
	// baseURLErr is why the base URL is refused, answered by every call.
	baseURLErr       error
	Benefits         *BenefitsService
	CheckoutLinks    *CheckoutLinksService
	Checkouts        *CheckoutsService
	CustomerSessions *CustomerSessionsService
	Customers        *CustomersService
	Discounts        *DiscountsService
	Disputes         *DisputesService
	Events           *EventsService
	Meters           *MetersService
	Orders           *OrdersService
	PaymentMethods   *PaymentMethodsService
	Payments         *PaymentsService
	Prices           *PricesService
	Products         *ProductsService
	Refunds          *RefundsService
	Subscriptions    *SubscriptionsService
	Usage            *UsageService
	Webhooks         *WebhooksService
}

// Option configures a Client.
type Option func(*Client)

// WithBaseURL points the client at another address, such as a local server.
// It must be https; http is accepted only for localhost, 127.0.0.0/8 and ::1,
// and any other address makes every call answer ErrInsecureBaseURL.
func WithBaseURL(baseURL string) Option {
	return func(c *Client) { c.baseURL = strings.TrimRight(baseURL, "/") }
}

// WithHTTPClient sends the requests through httpClient. The default client
// refuses redirects, so the API key never follows one; a client given here
// decides for itself.
func WithHTTPClient(httpClient *http.Client) Option {
	return func(c *Client) { c.http = httpClient }
}

// New is a client for the organization apiKey belongs to.
func New(apiKey string, opts ...Option) *Client {
	c := &Client{apiKey: apiKey, baseURL: DefaultBaseURL, http: &http.Client{
		Timeout: 30 * time.Second,
		// The API never redirects, and a redirect would carry the key along:
		// the 3xx is the answer, and an Error.
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
	}}
	for _, opt := range opts {
		opt(c)
	}
	c.baseURLErr = checkBaseURL(c.baseURL)
	c.initServices()
	return c
}

// checkBaseURL refuses an address that is not https, unless it is loopback.
func checkBaseURL(baseURL string) error {
	u, err := url.Parse(baseURL)
	if err != nil || u.Host == "" {
		return ErrInsecureBaseURL
	}
	switch strings.ToLower(u.Scheme) {
	case "https":
		return nil
	case "http":
		host := strings.ToLower(u.Hostname())
		if host == "localhost" {
			return nil
		}
		if ip := net.ParseIP(host); ip != nil && ip.IsLoopback() {
			return nil
		}
	}
	return ErrInsecureBaseURL
}

// RequestOption configures one call.
type RequestOption func(*requestConfig)

type requestConfig struct {
	idempotencyKey string
	apiKey         string
}

// WithIdempotencyKey makes a write safe to repeat: the same key with the same
// body answers the first response again; with another body, a 409. A POST
// without one is sent with a random key of its own, one a call.
func WithIdempotencyKey(key string) RequestOption {
	return func(r *requestConfig) { r.idempotencyKey = key }
}

// WithAPIKey sends this call with another organization's key.
func WithAPIKey(key string) RequestOption {
	return func(r *requestConfig) { r.apiKey = key }
}

func (c *Client) do(ctx context.Context, method, path string, query url.Values, body any, out any, opts []RequestOption) error {
	if c.baseURLErr != nil {
		return c.baseURLErr
	}
	config := requestConfig{apiKey: c.apiKey}
	for _, opt := range opts {
		opt(&config)
	}
	target := c.baseURL + path
	if len(query) > 0 {
		target += "?" + query.Encode()
	}
	var reader io.Reader
	if body != nil {
		encoded, err := json.Marshal(body)
		if err != nil {
			return err
		}
		reader = bytes.NewReader(encoded)
	}
	req, err := http.NewRequestWithContext(ctx, method, target, reader)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+config.apiKey)
	req.Header.Set("Accept", "application/json")
	req.Header.Set("User-Agent", "perata-go/"+Version)
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if config.idempotencyKey == "" && method == http.MethodPost {
		if config.idempotencyKey, err = newIdempotencyKey(); err != nil {
			return err
		}
	}
	if config.idempotencyKey != "" {
		req.Header.Set("Idempotency-Key", config.idempotencyKey)
	}
	resp, err := c.http.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		return err
	}
	if resp.StatusCode >= 300 {
		return errorOf(resp, raw)
	}
	if out == nil {
		// A 204, or any answer the caller does not read.
		return nil
	}
	envelope := struct {
		Data any `json:"data"`
	}{Data: out}
	return json.Unmarshal(raw, &envelope)
}

// newIdempotencyKey is a random UUID (version 4).
func newIdempotencyKey() (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	b[6] = b[6]&0x0f | 0x40
	b[8] = b[8]&0x3f | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:]), nil
}

func errorOf(resp *http.Response, raw []byte) *Error {
	e := &Error{StatusCode: resp.StatusCode}
	type problem struct {
		Error   string              `json:"error"`
		Message string              `json:"message"`
		Fields  map[string][]string `json:"fields"`
		Record  int                 `json:"record"`
	}
	// Every error is the problem itself (error, message, fields). Servers from before
	// that document wrapped the usage ingestion's errors in data: still read.
	var body struct {
		problem
		Data *problem `json:"data"`
	}
	if json.Unmarshal(raw, &body) == nil {
		found := body.problem
		if found.Error == "" && body.Data != nil {
			found = *body.Data
		}
		e.Code, e.Message, e.Fields, e.Record = found.Error, found.Message, found.Fields, found.Record
	}
	if seconds, err := strconv.Atoi(resp.Header.Get("Retry-After")); err == nil {
		e.RetryAfter = time.Duration(seconds) * time.Second
	}
	return e
}
